//go:build lance_native && cgo
package lancenative
import("context";"errors";"os";"path/filepath";"reflect";"testing")
func private(t *testing.T)string{t.Helper();path:=t.TempDir();if err:=os.Chmod(path,0700);err!=nil{t.Fatal(err)};return path}
func TestNativeExportMissingNeverCreatesDatabase(t *testing.T){root:=private(t);missing:=filepath.Join(root,"missing");if _,err:=Export(context.Background(),missing,private(t));err==nil{t.Fatal("absent database accepted")};if _,err:=os.Lstat(missing);!errors.Is(err,os.ErrNotExist){t.Fatal("absent database was created",err)}}
func TestNativeInputsAndCancellation(t *testing.T){for _,path:=range []string{"relative","/tmp/../tmp",string([]byte{'/',0})}{if _,err:=Export(context.Background(),path,private(t));!errors.Is(err,ErrInput){t.Fatal(err)}};root:=private(t);if _,err:=Export(nil,root,private(t));!errors.Is(err,ErrInput){t.Fatal(err)};ctx,cancel:=context.WithCancel(context.Background());cancel();if _,err:=Export(ctx,root,private(t));!errors.Is(err,context.Canceled){t.Fatal(err)};if _,err:=Import(ctx,root,private(t),Manifest{});!errors.Is(err,context.Canceled){t.Fatal(err)}}
func TestNativeRejectsMalformedStreamsWithoutOverwritingExistingStage(t *testing.T){input:=private(t);if err:=os.WriteFile(filepath.Join(input,"chunks.arrows"),[]byte("not an Arrow stream"),0600);err!=nil{t.Fatal(err)};stage:=private(t);manifest:=Manifest{Tables:[]Table{{Name:"chunks",Version:1,Rows:1,File:"chunks.arrows"}}};if _,err:=Import(context.Background(),stage,input,manifest);err==nil{t.Fatal("malformed Arrow admitted")};sentinel:=filepath.Join(stage,"do-not-overwrite");if err:=os.WriteFile(sentinel,[]byte("existing"),0600);err!=nil{t.Fatal(err)};if _,err:=Import(context.Background(),stage,input,manifest);err==nil{t.Fatal("nonempty stage admitted")};data,err:=os.ReadFile(sentinel);if err!=nil||string(data)!="existing"{t.Fatal("existing content overwritten",err)}}
func TestNativeRefusesEscapingManifestAndSymlinkRoots(t *testing.T){input:=private(t);for _,item:=range []Table{{Name:"../chunks",File:"../outside.arrows"},{Name:"chunks",File:"../outside.arrows"},{Name:"arbitrary",File:"arbitrary.arrows"}}{if _,err:=Import(context.Background(),private(t),input,Manifest{Tables:[]Table{item}});err==nil{t.Fatal("manifest escape accepted",item)}};root:=private(t);actual:=private(t);alias:=filepath.Join(root,"alias");if err:=os.Symlink(actual,alias);err!=nil{t.Fatal(err)};if _,err:=Export(context.Background(),alias,private(t));err==nil{t.Fatal("symlink db accepted")};if err:=EnsureExistingCopy(alias);!errors.Is(err,ErrInput){t.Fatal(err)}}
func TestNativeRepeatFailureFreeAndZeroReports(t *testing.T){root:=private(t);for range 16{result,err:=Export(context.Background(),filepath.Join(root,"missing"),private(t));if err==nil||!reflect.DeepEqual(result,Manifest{}){t.Fatal(result,err)}}}
